class Skiplist:
    MAX_LEVEL = 16

    class Node:
        def __init__(self, val, level):
            self.val = val
            self.next = [None] * level

    def __init__(self):
        self.head = self.Node(-1, self.MAX_LEVEL)
        self.level = 1

    def _random_level(self):
        lv = 1
        while random.random() < 0.5 and lv < self.MAX_LEVEL:
            lv += 1
        return lv

    def search(self, target):
        curr = self.head
        for i in range(self.level - 1, -1, -1):
            while curr.next[i] and curr.next[i].val < target:
                curr = curr.next[i]
        curr = curr.next[0]
        return curr is not None and curr.val == target

    def add(self, num):
        update = [self.head] * self.MAX_LEVEL
        curr = self.head
        for i in range(self.level - 1, -1, -1):
            while curr.next[i] and curr.next[i].val < num:
                curr = curr.next[i]
            update[i] = curr
        lv = self._random_level()
        if lv > self.level:
            for i in range(self.level, lv):
                update[i] = self.head
            self.level = lv
        new_node = self.Node(num, lv)
        for i in range(lv):
            new_node.next[i] = update[i].next[i]
            update[i].next[i] = new_node

    def erase(self, num):
        update = [None] * self.MAX_LEVEL
        curr = self.head
        for i in range(self.level - 1, -1, -1):
            while curr.next[i] and curr.next[i].val < num:
                curr = curr.next[i]
            update[i] = curr
        target = update[0].next[0]
        if not target or target.val != num:
            return False
        for i in range(self.level):
            if update[i].next[i] != target:
                break
            update[i].next[i] = target.next[i]
        return True

