def splitListInParts(head, k):
    n = 0
    cur = head
    while cur:
        n += 1
        cur = cur.next
    base, extra = n // k, n % k
    parts = []
    cur = head
    for i in range(k):
        part_head = cur
        part_size = base + (1 if i < extra else 0)
