class DoublyLinkedList:
    def __init__(self):
        self.head = DLLNode()
        self.tail = DLLNode()
        self.head.next = self.tail
        self.tail.prev = self.head
        self.size = 0

    def _insert_between(self, val, before, after):
        node = DLLNode(val)
        node.prev = before
        node.next = after
        before.next = node
        after.prev = node
        self.size += 1

    def _delete_node(self, node):
        node.prev.next = node.next
        node.next.prev = node.prev
        self.size -= 1

    def prepend(self, val):
        self._insert_between(val, self.head, self.head.next)

    def append(self, val):
        self._insert_between(val, self.tail.prev, self.tail)

    def deleteHead(self):
        if self.size:
            self._delete_node(self.head.next)

    def deleteTail(self):
        if self.size:
            self._delete_node(self.tail.prev)

    def toList(self):
        res = []
        cur = self.head.next
        while cur != self.tail:
            res.append(cur.val)
            cur = cur.next
        return res

